  "narrative": "Late-February polling suggests CDU is the most likely holder of the most seats in Baden-Württemberg, supported by seat projections that favor CDU. However, Greens narrowing the gap and turnout dynamics keep the outcome probabilistic rather than certain.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "reference class of Baden-Württemberg elections where CDU-leading polls and seat projections indicate CDU as the largest party, suitable for anchoring to pre-election expectations"
    },
    "factor_updates": [
      {
        "factor": "CDU leads in late-February polls (Infratest dimap)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Late Feb polls show CDU around 28% with Greens 27%, maintaining CDU as largest party and supporting the anchor."
      },
      {
        "factor": "Seat projections showing CDU ahead in credible models",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Seat projections (e.g., CDU 37 vs Greens 35 in a 120-seat Landtag under some models) reinforce CDU as largest party."
      },
      {
        "factor": "Greens closing the gap, narrowing CDU lead",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens rising to mid-to-high 20s reduces CDU margin, increasing risk of not expanding seat share as much."
